import{_ as n,C as a,o as l,c as h,a2 as t,j as r,G as o}from"./chunks/framework.BgSoyxN5.js";const b=JSON.parse('{"title":"Sector Rotation: Leadership, Not Just Green Candles | TickerForge","description":"Separating sectors that actually lead from sectors merely rising with the market, on two axes — absolute trend and relative performance. What it answers and how to publish it in your channel.","frontmatter":{"title":"Sector Rotation: Leadership, Not Just Green Candles | TickerForge","description":"Separating sectors that actually lead from sectors merely rising with the market, on two axes — absolute trend and relative performance. What it answers and how to publish it in your channel.","aside":false,"locale":"en","alternateLocales":{"en":"/market-intelligence/sector-rotation","ru":"/ru/market-intelligence/sector-rotation"},"pageClass":"partners-page"},"headers":[],"relativePath":"market-intelligence/sector-rotation.md","filePath":"market-intelligence/sector-rotation.md","lastUpdated":1788182993000}'),c={name:"market-intelligence/sector-rotation.md"},d={class:"partners-wide"},p={class:"partners-post-gallery"};function u(m,e,g,w,f,k){const s=a("PartnerPostImage"),i=a("PartnerChannelCta");return l(),h("div",null,[e[0]||(e[0]=t('<h1 id="sector-rotation" tabindex="-1">Sector Rotation <a class="header-anchor" href="#sector-rotation" aria-label="Permalink to &quot;Sector Rotation&quot;">​</a></h1><p>&quot;Tech rallied today&quot; is not leadership. Everything rallied today. The useful question is which sectors rose <em>more than the market</em>, and whether that is new.</p><div class="partners-hero-actions"><a class="partners-button partners-button--primary" href="/methodology/sector-rotation">See how it is measured</a><a class="partners-button partners-button--secondary" href="#publish">Publish it in your channel</a></div><p class="partners-locale-switch"><a href="/ru/market-intelligence/sector-rotation" hreflang="ru">Читать эту страницу на русском</a></p><p class="partners-backlink"><a href="/market-intelligence/">All market intelligence reads</a> · <a href="/market-intelligence/market-regime">Market Regime</a> · <a href="/market-intelligence/market-stress">Market Stress</a></p><h2 id="answers" tabindex="-1">The Question It Answers <a class="header-anchor" href="#answers" aria-label="Permalink to &quot;The Question It Answers {#answers}&quot;">​</a></h2><p><strong>&quot;Where did leadership actually move — and is that a change?&quot;</strong></p><p>On a strong day almost every sector is green, and a feed reporting the biggest movers reports the market twice. Rotation is about relative behaviour: which sector pulled ahead of the index, which fell behind it, and whether the ordering is different from last week.</p><h2 id="why" tabindex="-1">Why Two Axes Beat A Leaderboard <a class="header-anchor" href="#why" aria-label="Permalink to &quot;Why Two Axes Beat A Leaderboard {#why}&quot;">​</a></h2><div class="partners-wide partners-wide--compact"><ul class="partners-feature-list"><li><strong>Absolute trend and relative performance are measured separately.</strong> A sector can be rising and losing ground at the same time. A single-axis leaderboard cannot express that; two axes can, and it is usually the more interesting state.</li><li><strong>Leadership changes are the event.</strong> The read is built to surface where the ordering shifted, not to restate that the market went up.</li><li><strong>Tactical and structural are different posts.</strong> A daily view answers what moved this week; a weekly one answers whether the structure changed. Conflating them is how a channel ends up calling every wiggle a rotation.</li><li><strong>It is most useful under a regime.</strong> Defensive leadership inside a <a href="/market-intelligence/market-regime">Recovery regime</a> is a contradiction worth writing about. Neither read alone shows it.</li></ul></div><h2 id="example" tabindex="-1">What The Post Looks Like <a class="header-anchor" href="#example" aria-label="Permalink to &quot;What The Post Looks Like {#example}&quot;">​</a></h2>',11)),r("div",d,[r("div",p,[o(s,{src:"/partners/examples/sector-rotation-sample.png",alt:"TickerForge Sector Rotation post: which sectors led, which lagged, and where leadership changed",caption:"Who led, who lagged, and what changed since last time."})])]),e[1]||(e[1]=t('<h2 id="method" tabindex="-1">How It Is Built <a class="header-anchor" href="#method" aria-label="Permalink to &quot;How It Is Built {#method}&quot;">​</a></h2><p>Two axes: absolute trend direction for each sector, and performance relative to the broad index. A sector&#39;s position is the pair, which is what separates &quot;rising&quot; from &quot;leading&quot;.</p><p>Full write-up: <a href="/methodology/sector-rotation">Sector rotation methodology</a>.</p><h2 id="publish" tabindex="-1">Two Ways To Use It <a class="header-anchor" href="#publish" aria-label="Permalink to &quot;Two Ways To Use It {#publish}&quot;">​</a></h2><div class="partners-wide partners-wide--compact"><ul class="partners-feature-list"><li><strong>Read it.</strong> Sector rotation posts run on the TickerForge public channel in both a daily and a weekly form.</li><li><strong>Publish it.</strong> Sector Rotation is available for partner pilots — say so on the <a href="/partners/market-news">Market News</a> page and we prioritise by what partners actually ask for.</li></ul></div>',5)),o(i),e[2]||(e[2]=t('<p>Rotation is context, not a signal. Leadership describes what has happened across sectors; it is not an instruction to rotate a portfolio. TickerForge is educational decision-support software, not financial advice.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/market-intelligence/">All market intelligence reads</a></li><li><a href="/methodology/sector-rotation">Sector rotation — methodology</a></li><li><a href="/market-intelligence/market-regime">Market Regime</a></li><li><a href="/partners/market-news">Market news partner program</a></li></ul>',3))])}const y=n(c,[["render",u]]);export{b as __pageData,y as default};
